        public void ReadOptimalInt32(out int value) => value = ReadOptimalInt32();

        /// <summary>A count, in the same encoding as <see cref="ReadOptimalInt32"/>.</summary>
        public int ReadCounter32() => ReadOptimalInt32();

        /// <summary>
        /// An int64 written in as few bytes as its magnitude needed, either sign.
        /// </summary>
        /// <remarks>
        /// The base of a bit-packed block, which is a value of the column's own element type -
        /// an i64 column's base does not fit in thirty-two bits. One byte when it is zero,
        /// which is what most columns carry.
        /// </remarks>
        public long ReadOptimalInt64()
