                if ((piece & 0x80) == 0)
                    break;

                shift += 7;

                if (shift > 63)
                    throw new TcbException("a 64-bit variable length integer runs past ten bytes");
            }

            return unchecked((long)(encoded >> 1) ^ -(long)(encoded & 1));
