            if (encoding > TcbTable.EncodingDeltaRle)
                throw new TcbException($"{fieldName}: encoding {encoding} cannot carry a packed byte stream");

            int filled = 0;
            int previous = 0;

            // The first value of a delta stream is written outright; the rest are steps from
