                    case TcbTable.EncodingVarint:
                        value = AsByte(ReadOptimalInt32(), fieldName);
                        break;

                    case TcbTable.EncodingDelta:
                        step = ReadOptimalInt32();
                        break;

                    case TcbTable.EncodingRle:
                        run = ReadCounter32();
                        value = AsByte(ReadOptimalInt32(), fieldName);
                        break;

                    default: // EncodingDeltaRle
                        run = ReadCounter32();
                        step = ReadOptimalInt32();
                        break;
                }

                if (run < 1 || run > count - filled)
                {
                    throw new TcbException(
                        $"{fieldName}: a run of {run} cannot cover the {count - filled} bytes left");
                }

                bool walking = encoding == TcbTable.EncodingDelta || encoding == TcbTable.EncodingDeltaRle;

                for (int at = 0; at < run; at++)
                {
                    if (walking)
                    {
                        previous = AsByte(unchecked(previous + step), fieldName);
                        bytes[filled++] = (byte)previous;
                    }
                    else
