            _position += count;

            return span;
        }

        private uint ReadVarint32()
        {
            uint value = 0;

            for (int shift = 0; shift < 35; shift += 7)
            {
                byte b = Take(1)[0];
                value |= (uint)(b & 0x7F) << shift;

                if ((b & 0x80) == 0)
