    /// <summary>
    /// One column as the file describes it: the descriptor the header carries per column.
    /// </summary>
    public struct TcbColumn
    {
        /// <summary>What identifies the column, instead of its position.</summary>
        public int Tag;

        /// <summary>Element type: one of the Element* constants.</summary>
        public byte Element;

        /// <summary>Kind: scalar or array.</summary>
        public byte Kind;

        /// <summary>How the block's values are laid out: one of the Encoding* constants.</summary>
        public byte Encoding;

        /// <summary>
        /// Whether the block begins with one presence bit per row, low bit first.
        /// </summary>
        /// <remarks>
        /// Set only where the sheet marked the column optional. The values themselves are
        /// still written for every row - a row without one carries the type's empty value -
        /// so the bitmap says which of those to believe and nothing about the layout after it.
        /// </remarks>
        public bool Nullable;

        /// <summary>
        /// Whether the block states, per element, which of an array's places hold a value.
        /// </summary>
        /// <remarks>
        /// Independent of <see cref="Nullable"/>: a column may say a row has no array, that
        /// an element of one has no value, or both. spec/types/nullable-array-elements.md.
        /// </remarks>
        public bool ElementNullable;

        /// <summary>Total bytes of the column's data block - what a skip advances by.</summary>
        public int ByteLength;
    }

    /// <summary>
    /// Reads one scalar column's values in row order, whatever the block's encoding.
    ///
    /// The generated row loop stays a row loop; this is the one place that knows how
    /// a delta accumulates, how long a run has left, or that a dictionary index is a
    /// reference into strings decoded once. That last one matters beyond file size: a
    /// hundred-thousand-row column with three distinct strings allocates three strings,
    /// not a hundred thousand.
    ///
    /// CheckColumn has already refused any (element, encoding) pair the spec does not
    /// define, so the switches here do not re-litigate that.
    /// </summary>
    public sealed class TcbColumnCursor
    {
        private readonly TcbReader _reader;
        private readonly string _fieldName;
        private readonly byte _element;
        private readonly byte _encoding;

        /// <summary>
        /// The block's dictionary, decoded once and handed out per row.
        ///
        /// One of these is non-null when the block has a dictionary at all, chosen by the
        /// element: strings are decoded to instances that rows then share, and a
        /// fixed-width element keeps its raw bytes so the value is reconstructed exactly
        /// as the raw layout would have read it.
        /// </summary>
        private readonly string[] _dictionary;

        private readonly byte[] _valueDictionary;
        private readonly int _valueWidth;

        // A run-length family's current run: what remains of it, and its value - which
        // is a plain value for RLE, a delta for DELTA_RLE, an index for DICT_RLE.
        private int _runRemaining;
        private int _runValue;

        // The delta family's accumulator, once _started.
        private int _previous;
        private bool _started;

        // Values not yet handed out. A run that claims more than this is corrupt, and
        // catching it here names the field instead of leaving it to the block-end check.
        // For an array column this counts elements, not rows.
        private int _rowsRemaining;

        /// <summary>
        /// How many elements each row holds, decoded up front for an encoded array column.
        /// </summary>
        /// <remarks>
        /// Up front because the element stream follows the length stream in the block, so
        /// every length has been read by the time the first element is. Null for a raw array,
        /// whose lengths are interleaved with its elements and read as they are reached.
        /// </remarks>
        private readonly int[] _lengths;

        private int _lengthAt;

        /// <summary>Whether a float column's values are travelling as integers.</summary>
        private readonly bool _wholeNumbers;

        /// <summary>
        /// A bit-packed column's bytes, decoded up front, and where in them the next value is.
        /// </summary>
        /// <remarks>
        /// Up front because the bytes are themselves under an encoding, and a value can cross
        /// a byte boundary - so handing values out one at a time would mean carrying a decoder
        /// and a bit offset that disagree about where they are. The byte count is known before
        /// the first read, so there is nothing to discover by streaming it.
        /// </remarks>
        private readonly byte[] _packed;
        private readonly int _packedWidth;
        private readonly long _packedBase;
        private long _packedBit;

        public TcbColumnCursor(TcbReader reader, in TcbColumn column, int rowCount, string fieldName)
        {
            _reader = reader;
            _fieldName = fieldName;
            _element = column.Element;
            _encoding = column.Encoding;
            _rowsRemaining = rowCount;

            _dictionary = null;
            _valueDictionary = null;
            _valueWidth = 0;
            _lengths = null;
            _wholeNumbers = false;
            _packed = null;
            _packedWidth = 0;
            _packedBase = 0;
            _packedBit = 0;

            // An array column's block names an encoding for its elements and, where its rows
            // differ in length, one for the lengths. Both are encodings that already exist,
            // so all this does is read them and then go on being the element stream's cursor.
            if (_encoding == TcbTable.EncodingArray)
            {
                reader.Read(out byte elementEncoding);
                _encoding = elementEncoding;

                reader.Read(out byte lengthEncoding);
                _lengths = ReadLengths(reader, lengthEncoding, rowCount, fieldName);

                long elements = 0;
                foreach (int length in _lengths)
                    elements += length;

                if (elements > int.MaxValue)
                    throw new TcbException($"{fieldName}: the column declares more elements than can be held");

                _rowsRemaining = (int)elements;
            }

            // A float column whose values are all whole numbers carries them as integers and
            // says which integer encoding they travel under. From here down it is that
            // encoding's cursor, and only the handing out converts back.
            if (_encoding == TcbTable.EncodingWhole)
            {
                reader.Read(out byte inner);

                if (inner < TcbTable.EncodingVarint || inner > TcbTable.EncodingDeltaRle)
                {
                    throw new TcbException(
                        $"{fieldName}: encoding {inner} cannot carry a whole-number column's values");
                }

                _encoding = inner;
                _wholeNumbers = true;
            }

            // A bit-packed column states the width its range needs, the base subtracted from
            // every value, and which encoding carries the packed bytes. Decoded here so that
            // handing values out is a shift and an add.
            if (_encoding == TcbTable.EncodingBitpack)
            {
                reader.Read(out byte width);
                long packedBase = reader.ReadOptimalInt64();
                reader.Read(out byte inner);

                if (width < 1 || width > 64)
                    throw new TcbException($"{fieldName}: a bit width of {width} is not between 1 and 64");

                _packedWidth = width;
                _packedBase = packedBase;

                long bits = (long)_rowsRemaining * width;
                long bytes = (bits + 7) / 8;

                if (bytes > int.MaxValue)
                    throw new TcbException($"{fieldName}: the packed stream is larger than can be held");

                _packed = reader.ReadByteStream(inner, (int)bytes, fieldName);

                return;
            }

            // A segment dictionary is built once, here, and from then on the block is a
            // dictionary with an index stream like any other - so the row-by-row paths below
            // need to know nothing about it.
            if (_encoding == TcbTable.EncodingDictSegment || _encoding == TcbTable.EncodingDictSegmentRle)
            {
                _dictionary = ReadSegmentDictionary(reader, fieldName);

                _encoding = _encoding == TcbTable.EncodingDictSegment
                    ? TcbTable.EncodingDict
                    : TcbTable.EncodingDictRle;

                return;
            }

            bool plainDictionary =
                _encoding == TcbTable.EncodingDict || _encoding == TcbTable.EncodingDictRle;

            bool frontDictionary =
                _encoding == TcbTable.EncodingDictFront || _encoding == TcbTable.EncodingDictFrontRle;

            if (!plainDictionary && !frontDictionary)
                return;

            int count = reader.ReadCounter32();
            if (count < 0)
                throw new TcbException($"{fieldName}: the dictionary entry count is negative");

            if (frontDictionary)
            {
                _dictionary = ReadFrontCodedDictionary(reader, count, fieldName);
                return;
            }

            if (_element == TcbTable.ElementString)
            {
                _dictionary = new string[count];

                for (int at = 0; at < count; at++)
                    reader.Read(out _dictionary[at]);

                return;
            }

            // A fixed-width element: the entries are the value's own bytes, so they are
            // taken as bytes and turned into values only when a row asks for one.
            _valueWidth = _element == TcbTable.ElementF32 ? 4 : 8;
            _valueDictionary = new byte[count * _valueWidth];

            for (int at = 0; at < count; at++)
                reader.Take(_valueWidth).CopyTo(new Span<byte>(_valueDictionary, at * _valueWidth, _valueWidth));
        }

        /// <summary>
        /// A sorted dictionary whose entries state only what they do not share with the
        /// entry before them.
        /// </summary>
        /// <remarks>
        /// Decoded into whole strings here rather than kept folded, because a row wants a
        /// string and the folding was only ever about the bytes on disk. The scratch
        /// buffer grows to the longest entry and is reused, so the allocations are the
        /// strings themselves - one per distinct value, which is the point.
        /// </remarks>
        private static string[] ReadFrontCodedDictionary(TcbReader reader, int count, string fieldName)
        {
            var entries = new string[count];
            var scratch = new byte[64];
            int previousLength = 0;

            for (int at = 0; at < count; at++)
            {
                int shared = reader.ReadCounter32();
                int rest = reader.ReadCounter32();

                if (shared < 0 || rest < 0 || shared > previousLength)
                {
                    throw new TcbException(
                        $"{fieldName}: dictionary entry {at} shares {shared} bytes with an entry " +
                        $"of {previousLength}");
                }

                int length = shared + rest;

                if (length > scratch.Length)
                {
                    int capacity = scratch.Length;
                    while (capacity < length)
                        capacity *= 2;

                    Array.Resize(ref scratch, capacity);
                }

                if (rest > 0)
                    reader.Take(rest).CopyTo(new Span<byte>(scratch, shared, rest));

                entries[at] = length == 0 ? string.Empty : Encoding.UTF8.GetString(scratch, 0, length);
                previousLength = length;
            }

            return entries;
        }

        /// <summary>
        /// How many elements the next row of an array column holds.
        /// </summary>
        /// <remarks>
        /// One call whichever way the block is laid out. An encoded array decoded every
        /// length before the first element was read, so this hands out what it already has;
        /// a raw one states each row's length in front of that row's elements, so this reads
        /// it where it stands.
        /// </remarks>
        public int NextLength()
        {
            if (_lengths != null)
            {
                if (_lengthAt >= _lengths.Length)
                    throw new TcbException($"{_fieldName}: the column has no more rows to read");

                return _lengths[_lengthAt++];
            }

            int length = _reader.ReadCounter32();

            if (length < 0)
                throw new TcbException($"{_fieldName}: a row declares {length} elements");

            return length;
        }

        /// <summary>
        /// The lengths of an array column's rows, as their own encoded stream.
        /// </summary>
        /// <remarks>
        /// A varint stream, so what may be chosen for it is what may be chosen for any varint
        /// column - each length as a counter32, or runs of them. Most columns have rows that
        /// are all the same length, which is one run.
        /// </remarks>
        private static int[] ReadLengths(TcbReader reader, byte encoding, int rowCount, string fieldName)
        {
            var lengths = new int[rowCount];

            if (encoding == TcbTable.EncodingRaw)
            {
                for (int at = 0; at < rowCount; at++)
                {
                    lengths[at] = reader.ReadCounter32();

                    if (lengths[at] < 0)
                        throw new TcbException($"{fieldName}: row {at} declares {lengths[at]} elements");
                }

                return lengths;
            }

            if (encoding != TcbTable.EncodingRle)
            {
                throw new TcbException(
                    $"{fieldName}: encoding {encoding} cannot carry an array column's row lengths");
            }

            int filled = 0;

            while (filled < rowCount)
            {
                int run = reader.ReadCounter32();
                int value = reader.ReadOptimalInt32();

                if (run < 1 || run > rowCount - filled)
                {
                    throw new TcbException(
                        $"{fieldName}: a run of {run} lengths cannot cover the {rowCount - filled} " +
                        "rows left in the column");
                }

                if (value < 0)
                    throw new TcbException($"{fieldName}: a row declares {value} elements");

                for (int at = 0; at < run; at++)
                    lengths[filled++] = value;
            }

            return lengths;
        }

        /// <summary>
        /// A dictionary whose entries are lists of references into a table of the pieces they
        /// are built from.
        /// </summary>
        /// <remarks>
        /// Two reads and a concatenation: the table, which is front coded because its own
        /// entries share their fronts, and then each value as the pieces it is made of. The
        /// result is the same array of whole strings every other dictionary produces, so
        /// nothing downstream of here knows which kind it came from.
        /// </remarks>
        private static string[] ReadSegmentDictionary(TcbReader reader, string fieldName)
        {
            int segmentCount = reader.ReadCounter32();

            if (segmentCount < 0)
                throw new TcbException($"{fieldName}: the segment count is negative");

            if (segmentCount > reader.Remaining)
            {
                throw new TcbException(
                    $"{fieldName}: a segment table of {segmentCount} entries is larger than the file can hold");
            }

            var segments = new byte[segmentCount][];
            int previousLength = 0;

            for (int at = 0; at < segmentCount; at++)
            {
                int shared = reader.ReadCounter32();
                int rest = reader.ReadCounter32();

                if (shared < 0 || rest < 0 || shared > previousLength)
                {
                    throw new TcbException(
                        $"{fieldName}: segment {at} shares {shared} bytes with an entry of {previousLength}");
                }

                var segment = new byte[shared + rest];

                if (shared > 0)
                    Array.Copy(segments[at - 1], segment, shared);

                if (rest > 0)
                    reader.Take(rest).CopyTo(new Span<byte>(segment, shared, rest));

                segments[at] = segment;
                previousLength = segment.Length;
            }

            int count = reader.ReadCounter32();

            if (count < 0)
                throw new TcbException($"{fieldName}: the dictionary entry count is negative");

            if (count > reader.Remaining)
            {
                throw new TcbException(
                    $"{fieldName}: a dictionary of {count} entries is larger than the file can hold");
            }

            var entries = new string[count];
            var scratch = new byte[64];

            for (int at = 0; at < count; at++)
            {
                int pieces = reader.ReadCounter32();

                if (pieces < 0)
                    throw new TcbException($"{fieldName}: dictionary entry {at} declares {pieces} pieces");

                int length = 0;

                for (int piece = 0; piece < pieces; piece++)
                {
                    int index = reader.ReadCounter32();

                    if ((uint)index >= (uint)segmentCount)
                    {
                        throw new TcbException(
                            $"{fieldName}: segment index {index} is out of range - the table " +
                            $"holds {segmentCount} entries");
                    }

                    var segment = segments[index];

                    if (length + segment.Length > scratch.Length)
                    {
                        int capacity = scratch.Length;
                        while (capacity < length + segment.Length)
                            capacity *= 2;

                        Array.Resize(ref scratch, capacity);
                    }

                    Array.Copy(segment, 0, scratch, length, segment.Length);
                    length += segment.Length;
                }

                entries[at] = length == 0 ? string.Empty : Encoding.UTF8.GetString(scratch, 0, length);
            }

            return entries;
        }

        /// <summary>
        /// The next value of a bit-packed stream: the packed bits, over the block's base.
        /// </summary>
        /// <remarks>
        /// A value may cross a byte boundary, so this walks bits rather than bytes. The
        /// addition wraps, mirroring the writer's wrapping subtraction; together they are
        /// exact for every pair.
        /// </remarks>
        private long NextPacked()
        {
            ulong slot = 0;

            for (int at = 0; at < _packedWidth; at++, _packedBit++)
            {
                if ((_packed[_packedBit >> 3] >> (int)(_packedBit & 7) & 1) != 0)
                    slot |= 1UL << at;
            }

            return unchecked(_packedBase + (long)slot);
        }

        /// <summary>The next int32 - which also serves enums, and reference indexes.</summary>
        public int NextI32()
        {
            _rowsRemaining--;

            if (_encoding == TcbTable.EncodingBitpack)
                return unchecked((int)NextPacked());

            switch (_encoding)
            {
                case TcbTable.EncodingRaw:
                {
                    if (_element == TcbTable.ElementI32)
                    {
                        _reader.Read(out int exact);
                        return exact;
                    }

                    return _reader.ReadOptimalInt32();
                }

                case TcbTable.EncodingVarint:
                    return _reader.ReadOptimalInt32();

                case TcbTable.EncodingDelta:
                {
                    // The addition wraps on purpose, mirroring the writer's wrapping
                    // subtraction; together they are exact for every int32 pair.
                    if (_started)
                        _previous = unchecked(_previous + _reader.ReadOptimalInt32());
                    else
                    {
                        _previous = _reader.ReadOptimalInt32();
                        _started = true;
                    }

                    return _previous;
                }

                case TcbTable.EncodingRle:
                {
                    if (_runRemaining == 0)
                        ReadRun();

                    _runRemaining--;
                    return _runValue;
                }

                default: // EncodingDeltaRle; CheckColumn refused everything else.
                {
                    if (!_started)
                    {
                        _previous = _reader.ReadOptimalInt32();
                        _started = true;
                        return _previous;
                    }

                    if (_runRemaining == 0)
                        ReadRun();

                    _runRemaining--;
                    _previous = unchecked(_previous + _runValue);
                    return _previous;
                }
            }
        }

        /// <summary>
        /// An int64 member: from an i64 column raw or through its dictionary, and from
        /// anything narrower by decoding an int32 and widening it.
        /// </summary>
        public long NextI64()
        {
            if (_element != TcbTable.ElementI64)
                return NextI32();

            if (_encoding == TcbTable.EncodingBitpack)
            {
                _rowsRemaining--;
                return NextPacked();
            }

            if (_valueDictionary != null)
                return BinaryPrimitives.ReadInt64LittleEndian(NextValueEntry());

            _rowsRemaining--;
            _reader.Read(out long exact);

            return exact;
        }

        /// <summary>A float member: raw, the dictionary entry's exact bit pattern, or a whole number.</summary>
        public float NextF32()
        {
            if (_wholeNumbers)
                return NextI32();

            if (_valueDictionary != null)
                return BitConverter.Int32BitsToSingle(BinaryPrimitives.ReadInt32LittleEndian(NextValueEntry()));

            _rowsRemaining--;
            _reader.Read(out float value);

            return value;
        }

        /// <summary>
        /// A double member: from f64 or f32 - either of them raw or dictionary-encoded -
        /// and from an i32 column by decoding and widening.
        /// </summary>
        public double NextF64()
        {
            if (_wholeNumbers)
                return NextI32();

            switch (_element)
            {
                case TcbTable.ElementF64:
                {
                    if (_valueDictionary != null)
                        return BitConverter.Int64BitsToDouble(BinaryPrimitives.ReadInt64LittleEndian(NextValueEntry()));

                    _rowsRemaining--;
                    _reader.Read(out double exact);

                    return exact;
                }

                case TcbTable.ElementF32:
                    return NextF32();

                default:
                    return NextI32();
            }
        }

        /// <summary>A bool member: one byte raw, a run of them, or one packed bit.</summary>
        public bool NextBool()
        {
            if (_encoding == TcbTable.EncodingRle || _encoding == TcbTable.EncodingBitpack)
                return NextI32() != 0;

            _rowsRemaining--;
            _reader.Read(out bool value);

            return value;
        }

        /// <summary>
        /// The bytes of the next row's dictionary entry, for a fixed-width element.
        /// </summary>
        private ReadOnlySpan<byte> NextValueEntry()
        {
            _rowsRemaining--;

            int index;

            if (_encoding == TcbTable.EncodingDict)
                index = _reader.ReadCounter32();
            else
            {
                if (_runRemaining == 0)
                    ReadRun();

                _runRemaining--;
                index = _runValue;
            }

            int count = _valueDictionary.Length / _valueWidth;

            if ((uint)index >= (uint)count)
            {
                throw new TcbException(
                    $"{_fieldName}: dictionary index {index} is out of range - the " +
                    $"dictionary holds {count} entries");
            }

            return new ReadOnlySpan<byte>(_valueDictionary, index * _valueWidth, _valueWidth);
        }

        /// <summary>The next string - the dictionary's instance where the block has one.</summary>
        public string NextString()
        {
            _rowsRemaining--;

            switch (_encoding)
            {
                case TcbTable.EncodingRaw:
                {
                    _reader.Read(out string value);
                    return value;
                }

                case TcbTable.EncodingDict:
                case TcbTable.EncodingDictFront:
                    return DictionaryEntry(_reader.ReadCounter32());

                default: // EncodingDictRle and EncodingDictFrontRle
                {
                    if (_runRemaining == 0)
                        ReadRun();

                    _runRemaining--;
                    return DictionaryEntry(_runValue);
                }
            }
        }

        /// <summary>
        /// Up to <paramref name="limit"/> rows that all hold the next value, and that
        /// value. Always at least 1.
        ///
        /// This is what makes a run cost one call instead of one per row: the generated
        /// loop asks once, then assigns the value that many times. An encoding that
        /// cannot promise sameness cheaply answers 1, so the caller's loop is correct
        /// over every encoding and only faster over runs.
        /// </summary>
        public int NextSameI32(int limit, out int value)
        {
            if (_encoding == TcbTable.EncodingRle)
            {
                _rowsRemaining--;
                if (_runRemaining == 0)
                    ReadRun();

                int n = _runRemaining < limit ? _runRemaining : limit;
                _runRemaining -= n;
                _rowsRemaining -= n - 1;
                value = _runValue;
                return n;
            }

            if (_encoding == TcbTable.EncodingDeltaRle && _started)
            {
                _rowsRemaining--;
                if (_runRemaining == 0)
                    ReadRun();

                if (_runValue == 0)
                {
                    // A zero-delta run is a run of one value.
                    int n = _runRemaining < limit ? _runRemaining : limit;
                    _runRemaining -= n;
                    _rowsRemaining -= n - 1;
                    value = _previous;
                    return n;
                }

                _runRemaining--;
                _previous = unchecked(_previous + _runValue);
                value = _previous;
                return 1;
            }

            value = NextI32();
            return 1;
        }

        /// <summary>The string counterpart of <see cref="NextSameI32"/>.</summary>
        public int NextSameString(int limit, out string value)
        {
            if (_encoding == TcbTable.EncodingDictRle || _encoding == TcbTable.EncodingDictFrontRle)
            {
                _rowsRemaining--;
                if (_runRemaining == 0)
                    ReadRun();

                int n = _runRemaining < limit ? _runRemaining : limit;
                _runRemaining -= n;
                _rowsRemaining -= n - 1;
                value = DictionaryEntry(_runValue);
                return n;
            }

            value = NextString();
            return 1;
        }

        private void ReadRun()
        {
            int length = _reader.ReadCounter32();

            // + 1 because the row this run was read for is already counted out of
            // _rowsRemaining by its Next call.
            if (length < 1 || length > _rowsRemaining + 1)
            {
                throw new TcbException(
                    $"{_fieldName}: a run of {length} values cannot cover the " +
                    $"{_rowsRemaining + 1} rows left in the column");
            }

            _runRemaining = length;
            _runValue = _reader.ReadOptimalInt32();
        }

        private string DictionaryEntry(int index)
        {
            if ((uint)index >= (uint)_dictionary.Length)
            {
                throw new TcbException(
                    $"{_fieldName}: dictionary index {index} is out of range - the " +
                    $"dictionary holds {_dictionary.Length} entries");
            }

            return _dictionary[index];
        }
    }

    /// <summary>
    /// The file-level parts of the format, shared by every generated table.
    /// </summary>
    public static class TcbTable
    {
        /// <summary>Version stamped at the head of every table file by the exporter.</summary>
        /// <remarks>
        /// The format is column-oriented and self-describing: the header names every column
        /// and how long its block is, and a reader that meets a version it does not know
        /// stops rather than guessing. 102 replaced 101 outright - a descriptor gained its
        /// encoding byte - before any 101 file had shipped. 104 is the current one: four
        /// encodings joined the nine, and the flags byte gained a meaning.
        /// </remarks>
        public const uint FormatVersion = 107;

        public const byte ElementVarint = 0;
        public const byte ElementBool = 1;
        public const byte ElementI32 = 2;
        public const byte ElementI64 = 3;
        public const byte ElementF32 = 4;
        public const byte ElementF64 = 5;
        public const byte ElementString = 6;
        public const byte ElementUuid = 7;

        public const byte KindScalar = 0;

        /// <summary>
        /// The only array kind: every row states its own length. A fixed-length kind sat at
        /// 1 until v107 and was removed rather than kept beside this one, because a length
        /// stated once is a length the generated code bakes in - and then a column added to
        /// a group needs the consumer rebuilt.
        /// </summary>
        public const byte KindArray = 1;

        // How a block's values are laid out. Raw is the layout 101 had; the others
        // compress a column that repeats itself, which static game data does
        // relentlessly. spec/wire/tcb-v102-column-encoding.md is the byte-level contract.
        public const byte EncodingRaw = 0;
        public const byte EncodingVarint = 1;
        public const byte EncodingDelta = 2;
        public const byte EncodingRle = 3;
        public const byte EncodingDeltaRle = 4;
        public const byte EncodingDict = 5;
        public const byte EncodingDictRle = 6;
        public const byte EncodingDictFront = 7;
        public const byte EncodingDictFrontRle = 8;

        // Composition rather than layout. An array block names an encoding for its elements
        // and one for its rows' lengths, and a whole-number float block names the integer
        // encoding its values travel under - so both are decoded by the cursors that already
        // exist, one level down, and neither adds a decode step anywhere.
        public const byte EncodingArray = 9;
        public const byte EncodingWhole = 10;

        // A dictionary whose entries are built from a shared table of the pieces they are
        // made of, which reaches what two values share in the middle and at the end where
        // front coding can only reach what they share at the front.
        public const byte EncodingDictSegment = 11;
        public const byte EncodingDictSegmentRle = 12;

        /// <summary>An integer stream at the width its own range needs, over a base.</summary>
        public const byte EncodingBitpack = 13;

        // The file header, at fixed offsets whether or not the file is encrypted and whether
        // or not it carries a MAC. spec/wire/tcb-mac-and-signature.md.
        public const int MagicOffset = 0;
        public const int VersionOffset = 4;
        public const int FlagsOffset = 8;
        public const int CipherOffset = 9;
        public const int NonceOffset = 10;
        public const int MacOffset = 22;
        public const int KeyCheckOffset = 38;

        /// <summary>
        /// The signature, as the fixed32 it is on disk: 'S' 'C' 'B' 0, little endian.
        /// </summary>
        /// <remarks>
        /// The same four bytes serve twice. At offset zero they are the file format
        /// signature, in the clear whether or not the file is encrypted. At the key check
        /// they are under the key, so a file that decrypts to something else was written with
        /// a different key - which is the one thing no structural check can tell from damage.
        /// </remarks>
        public const uint Magic = 0x00424354;

        /// <summary>Where the body begins. The header before it is always this long.</summary>
        public const int HeaderSize = 42;

        public const int NonceSize = 12;
        public const int MacSize = 16;

        /// <summary>Bit 0 of the flags byte: from the key check on, the file is ciphertext.</summary>
        public const byte FlagEncrypted = 0x01;

        /// <summary>The cipher byte of a file that is not encrypted.</summary>
        public const byte CipherNone = 0;

        /// <summary>The only cipher the format defines.</summary>
        public const byte CipherChaCha20 = 1;

        /// <summary>
        /// A file's plaintext bytes, checked against its MAC on the way.
        /// </summary>
        /// <remarks>
        /// Call this on the bytes before handing them to a reader. A file that is neither
        /// encrypted nor authenticated comes back untouched, so the call belongs in the load
        /// path whether or not the project uses either.
        ///
        /// The order is verify, then decrypt. The tag covers the file as it is stored, so an
        /// altered file is refused before the key is used on it, and the header - the flags,
        /// the cipher byte, the nonce - is covered along with the body.
        ///
        /// Decryption happens in place, and what comes back is a window onto the same array
        /// rather than a copy of it. The fields this consumes are returned to what a plain
        /// file has in them, so calling it twice on the same array is the same as calling it
        /// once.
        ///
        /// What the two layers are and are not for: both keys ship inside the client that
        /// reads the file. Encryption stops a data file being read in an editor; the MAC
        /// stops an edited one loading. Neither stops anyone who can take the keys out of the
        /// client, and no format does.
        /// </remarks>
        /// <param name="macKey">
        /// The key the files were signed with, or null when the project does not use one. A
        /// reader that has one refuses a file that carries no MAC: the field being zero is how
        /// a file says it is unauthenticated, so accepting that from a project that signs its
        /// files would put the check sixteen zero bytes away from being removed.
        /// </param>
        /// <param name="verifyMac">
        /// False skips the check. For tools and for measuring load time - and no weaker than
        /// it looks, because anyone who can flip this flag in a shipped binary can read the
        /// key out of the same binary.
        /// </param>
        public static ReadOnlyMemory<byte> Open(
            byte[] data, byte[] key, byte[] macKey = null, bool verifyMac = true)
        {
            if (data == null)
                throw new ArgumentNullException(nameof(data));

            if (data.Length < HeaderSize)
                throw new TcbException("the file is too short to be a table");

            if (BinaryPrimitives.ReadUInt32LittleEndian(new ReadOnlySpan<byte>(data, MagicOffset, 4))
                != Magic)
            {
                throw new TcbException("the file does not begin with the table file signature");
            }

            if (verifyMac)
                CheckMac(data, macKey);

            if ((data[FlagsOffset] & FlagEncrypted) == 0)
                return data;

            if (data[CipherOffset] != CipherChaCha20)
            {
                throw new TcbException(
                    $"the file uses cipher {data[CipherOffset]}, which this reader does not know");
            }

            if (key == null || key.Length != 32)
            {
                throw new TcbException(
                    "the file is encrypted and no key, or a key that is not 32 bytes, was given");
            }

            ChaCha20.Apply(
                key,
                new ReadOnlySpan<byte>(data, NonceOffset, NonceSize),
                new Span<byte>(data, KeyCheckOffset, data.Length - KeyCheckOffset));

            if (BinaryPrimitives.ReadUInt32LittleEndian(new ReadOnlySpan<byte>(data, KeyCheckOffset, 4))
                != Magic)
            {
                throw new TcbException(
                    "the file did not decrypt to a table - the key is not the one it was written with");
            }

            // Back to what a plain file holds in these bytes, so that a second call over the
            // same array passes it through instead of decrypting it again.
            data[FlagsOffset] &= unchecked((byte)~FlagEncrypted);
            data[CipherOffset] = CipherNone;

            for (int at = 0; at < NonceSize; at++)
                data[NonceOffset + at] = 0;

            return data;
        }

        /// <summary>
        /// The MAC field against the file's own bytes, and against whether a key was given.
        /// </summary>
        private static void CheckMac(byte[] data, byte[] macKey)
        {
            bool present = false;

            for (int at = 0; at < MacSize && !present; at++)
                present = data[MacOffset + at] != 0;

            if (macKey == null)
            {
                // Nothing to check with. A file that carries a tag is read anyway rather than
                // refused: this reader has no way to tell whether the tag is good, and a
                // client built before the project turned MACs on is one this format has
                // promised can still read the data it is sent.
                return;
            }

            if (macKey.Length != 32)
                throw new TcbException("the MAC key given is not 32 bytes");

            if (!present)
            {
                throw new TcbException(
                    "the file carries no MAC and this build expects one - it was exported "
                    + "without a MAC key, or the field was cleared after it was written");
            }

            if (!TcbMac.Verify(data, macKey))
            {
                throw new TcbException(
                    "the file does not match its MAC - it was altered after it was exported, "
                    + "or it was signed with a different key");
            }
        }

        /// <summary>
        /// Reads and checks the file header, returning the row count and the column
        /// descriptors the data blocks follow.
        /// </summary>
        public static TcbColumn[] ReadHeader(TcbReader reader, out int rowCount)
        {
            reader.Read(out uint magic);

            // Checked again here rather than only in Open, because a reader can be handed
            // bytes that never went through it.
            if (magic != Magic)
                throw new TcbException("the file does not begin with the table file signature");

            reader.Read(out uint version);
            if (version != FormatVersion)
            {
                throw new TcbException(
                    $"table format version {version} is not supported (expected {FormatVersion})");
            }

            reader.Read(out byte reserved);

            // Still every bit, bit 0 included. Open clears it on a file it has decrypted, so
            // reaching here with it set means the bytes were handed straight to the reader
            // without the key - and saying so beats letting the structural checks make what
            // they can of ciphertext.
            if ((reserved & FlagEncrypted) != 0)
            {
                throw new TcbException(
                    "the table is encrypted and was not decrypted - pass the key through Open first");
            }

            if (reserved != 0)
                throw new TcbException("table declares unsupported features");

            // The cipher byte, the nonce, the MAC and the key check. Open has dealt with all
            // four by now; what is left is to be standing at the body.
            reader.Skip(HeaderSize - CipherOffset);

            rowCount = reader.ReadCounter32();
            if (rowCount < 0)
                throw new TcbException("table row count is negative");

            int columnCount = reader.ReadCounter32();
            if (columnCount < 0)
                throw new TcbException("table column count is negative");

            var columns = new TcbColumn[columnCount];

            for (int at = 0; at < columnCount; at++)
            {
                columns[at].Tag = reader.ReadCounter32();

                reader.Read(out byte wire);
                columns[at].Element = (byte)(wire & 0x0F);
                columns[at].Kind = (byte)((wire >> 4) & 0x03);
                columns[at].Nullable = (wire & 0x40) != 0;
                columns[at].ElementNullable = (wire & 0x80) != 0;

                reader.Read(out columns[at].Encoding);

                reader.Read(out uint byteLength);
                columns[at].ByteLength = (int)byteLength;
            }

            // What the descriptors say about the file, checked before anybody allocates for the
            // row count. The blocks are all that follows the header, so their declared lengths have
            // to add up to the bytes left. A raw block also costs at least one byte per row - a
            // varint's shortest form, an empty string's length prefix, a variable array's counter -
            // so a larger row count is one the exporter could not have written. An encoded block
            // has no such floor (one run can cover any number of rows); its decode checks run
            // sums and dictionary bounds instead.

            int available = reader.Remaining;
            int declared = 0;

            foreach (var column in columns)
            {
                if (column.ByteLength < 0 || column.ByteLength > available - declared)
                {
                    throw new TcbException(
                        $"column tag {column.Tag} declares {column.ByteLength} bytes, which the " +
                        "file cannot hold");
                }

                declared += column.ByteLength;

                if (column.Encoding == EncodingRaw && rowCount > column.ByteLength)
                {
                    throw new TcbException(
                        $"the row count {rowCount} is larger than column tag {column.Tag} can " +
                        $"hold in its {column.ByteLength} bytes");
                }

            }

            if (declared != available)
            {
                throw new TcbException(
                    $"the columns declare {declared} bytes but {available} follow the header");
            }

            return columns;
        }

        /// <summary>
        /// That a column is what the generated member expects, or a lossless promotion of it.
        /// </summary>
        /// <remarks>
        /// Refusal is by name and by both types, never by reading anyway: a value that might
        /// not survive the conversion is a value this format does not read. What each member
        /// accepts is decided at generation time - the accepted list is in the generated call.
        /// </remarks>
        /// <summary>
        /// The one, two and three element forms the generated code actually emits.
        /// </summary>
        /// <remarks>
        /// Rather than one `params` overload, which allocates an array per column per load
        /// for a list that is never longer than three and is known at generation time.
        /// </remarks>
        public static void CheckColumn(
            in TcbColumn column, string fieldName, byte kind, bool nullable, byte accepted,
            bool elementNullable = false)
        {
            CheckShape(column, fieldName, kind, nullable, elementNullable);

            if (column.Element != accepted)
                throw ElementMismatch(column, fieldName);
        }

        public static void CheckColumn(
            in TcbColumn column, string fieldName, byte kind, bool nullable,
            byte accepted, byte alsoAccepted, bool elementNullable = false)
        {
            CheckShape(column, fieldName, kind, nullable, elementNullable);

            if (column.Element != accepted && column.Element != alsoAccepted)
                throw ElementMismatch(column, fieldName);
        }

        public static void CheckColumn(
            in TcbColumn column, string fieldName, byte kind, bool nullable,
            byte accepted, byte alsoAccepted, byte andAccepted, bool elementNullable = false)
        {
            CheckShape(column, fieldName, kind, nullable, elementNullable);

            if (column.Element != accepted && column.Element != alsoAccepted
                && column.Element != andAccepted)
            {
                throw ElementMismatch(column, fieldName);
            }
        }

        /// <summary>
        /// Reads a nullable column's presence bitmap, or returns null for a column that has
        /// none - which is every column the sheet did not mark optional.
        /// </summary>
        /// <remarks>
        /// Called by the generated code before the row loop, because the bitmap sits at the
        /// front of the block and the values follow it. One bit per row, low bit first,
        /// padded to a byte.
        ///
        /// A byte array rather than a bool per row: a hundred-thousand-row column costs
        /// 12 KB here and 100 KB the other way, and it is transient either way.
        /// </remarks>
        public static byte[] ReadPresence(TcbReader reader, in TcbColumn column, int rowCount)
        {
            if (!column.Nullable)
                return null;

            // The bitmap is a bit-packed boolean column of width one, so it carries an
            // encoding byte and is laid out by the same choice a packed value block uses.
            // Its width and base are known in advance, which is why it does not carry them.
            reader.Read(out byte encoding);

            return reader.ReadByteStream(encoding, (rowCount + 7) / 8, "a presence bitmap");
        }

        /// <summary>
        /// The element bitmap at the front of a block, or null where there is none.
        /// </summary>
        /// <remarks>
        /// Behind the row bitmap and in front of the values. Its length is written ahead of
        /// it as a counter32, because a variable-length column's total is the sum of row
        /// lengths and those live inside the value block - a reader meeting the bitmap first
        /// would have nothing to size it by.
        ///
        /// One bit per element written, in the order the block wrote them, so a reader walks
        /// it with a counter that steps once per element of every row.
        /// </remarks>
        public static byte[] ReadElementPresence(TcbReader reader, in TcbColumn column)
        {
            if (!column.ElementNullable)
                return null;

            int elements = reader.ReadCounter32();

            reader.Read(out byte encoding);

            return reader.ReadByteStream(encoding, (elements + 7) / 8, "an element presence bitmap");
        }

        /// <summary>Whether a row has a value, for a column that says which do.</summary>
        /// <remarks>
        /// A null bitmap means the column is not optional, and then every row has one - so
        /// the generated code can call this unconditionally.
        /// </remarks>
        public static bool IsPresent(byte[] presence, int row)
            => presence is null || (presence[row >> 3] & (1 << (row & 7))) != 0;

        private static void CheckShape(
            in TcbColumn column, string fieldName, byte kind, bool nullable,
            bool elementNullable = false)
        {
            // The same statement the nullability check below makes, about the other bitmap:
            // generated code that was not expecting one would read it as values.
            if (column.ElementNullable != elementNullable)
            {
                throw new TcbException(
                    $"{fieldName}: the file and the generated member disagree about whether this column's elements are optional" +
                    $" (file: {(column.ElementNullable ? "optional" : "required")}, " +
                    $"member: {(elementNullable ? "optional" : "required")}). " +
                    "The schema changed; regenerate the code or rebuild the data.");
            }

            // Nullability is part of the shape: a file that says a column is optional puts a
            // presence bitmap at the front of its block, and generated code that was not
            // expecting one would read the bitmap as values. Adding or removing a `?` is
            // therefore a schema change like any other, and it is caught here rather than in
            // whatever the misread bytes happened to mean.
            if (column.Nullable != nullable)
            {
                throw new TcbException(
                    $"{fieldName}: the file and the generated member disagree about whether this column is optional" +
                    $" (file: {(column.Nullable ? "optional" : "required")}, " +
                    $"member: {(nullable ? "optional" : "required")}). " +
                    "The schema changed; regenerate the code or rebuild the data.");
            }

            // Shape is the kind alone since v107. How many elements a row holds is what the
            // file states, row by row, so a group that grew a column is read rather than
            // refused - while a scalar that became an array is still a different shape.
            if (column.Kind != kind)
            {
                throw new TcbException(
                    $"{fieldName}: the file's column (kind {column.Kind}) does not " +
                    $"match the generated member (kind {kind}). The schema changed shape; " +
                    "regenerate the code or rebuild the data.");
            }

            // An encoding this build cannot decode - or one the spec does not define
            // for this element - is refused by name, exactly like an element it cannot
            // read. An unknown column's encoding never gets here: a skip is a skip
            // whatever the block's layout.
            if (!EncodingSupported(column))
            {
                throw new TcbException(
                    $"{fieldName}: the file's column uses encoding {column.Encoding}, which this " +
                    "reader cannot decode for its element type. Regenerate the code or rebuild " +
                    "the data.");
            }
        }

        /// <summary>
        /// The (element, encoding) pairs the spec defines. Integers take the integer
        /// encodings, strings the dictionary ones, and an array takes the composition that
        /// applies all of those to its elements.
        /// </summary>
        private static bool EncodingSupported(in TcbColumn column)
        {
            if (column.Encoding == EncodingRaw)
                return true;

            // An array's block says what its elements use, and the element encoding is
            // checked as it is read rather than here - the descriptor carries only the outer
            // one, so this is as far as the descriptor can be checked.
            if (column.Kind != KindScalar)
                return column.Encoding == EncodingArray;

            switch (column.Element)
            {
                case ElementBool:
                case ElementVarint:
                    return column.Encoding == EncodingRle || column.Encoding == EncodingBitpack;

                case ElementI32:
                    return (column.Encoding >= EncodingVarint && column.Encoding <= EncodingDeltaRle)
                        || column.Encoding == EncodingBitpack;

                // The dictionary is parameterized by element, so these three reach it
                // with entries that are simply their own raw bytes.
                case ElementI64:
                    return column.Encoding == EncodingDict || column.Encoding == EncodingDictRle
                        || column.Encoding == EncodingBitpack;

                // A float column additionally reaches the integer encodings, through the
                // block that says its values are whole numbers.
                case ElementF32:
                case ElementF64:
                    return column.Encoding == EncodingDict || column.Encoding == EncodingDictRle
                        || column.Encoding == EncodingWhole;

                // And a string dictionary can be front coded or built from segments, both of
                // which are meaningless for a fixed-width element and refused for one.
                case ElementString:
                    return (column.Encoding >= EncodingDict && column.Encoding <= EncodingDictFrontRle)
                        || column.Encoding == EncodingDictSegment
                        || column.Encoding == EncodingDictSegmentRle;

                default:
                    return false;
            }
        }

        private static TcbException ElementMismatch(
            in TcbColumn column, string fieldName)
            => new TcbException(
                $"{fieldName}: the file carries element type {column.Element}, which this member " +
                "cannot read. The column changed type incompatibly; regenerate the code or " +
                "rebuild the data.");

        /// <summary>
        /// The general form, for an accepted list longer than three. Nothing emits one today.
        /// </summary>
        public static void CheckColumn(
            in TcbColumn column, string fieldName, byte kind, bool nullable,
            params byte[] acceptedElements)
        {
            CheckShape(column, fieldName, kind, nullable);

            for (int at = 0; at < acceptedElements.Length; at++)
            {
                if (column.Element == acceptedElements[at])
                    return;
            }

            throw new TcbException(
                $"{fieldName}: the file carries element type {column.Element}, which this member " +
                $"cannot read (accepts: {string.Join(", ", acceptedElements)}). The column changed " +
                "type incompatibly; regenerate the code or rebuild the data.");
        }

        /// <summary>
        /// That a block was consumed exactly. A mismatch means the reader and writer disagree
        /// about the format, and stopping here names the column instead of corrupting the next.
        /// </summary>
        public static void CheckBlockEnd(TcbReader reader, in TcbColumn column, int expectedEnd)
        {
            if (reader.Position != expectedEnd)
            {
                throw new TcbException(
                    $"column tag {column.Tag}: its block declared {column.ByteLength} bytes but the " +
                    $"read ended {expectedEnd - reader.Position} bytes short of its boundary");
            }
        }

        /// <summary>Reads a whole file into memory.</summary>
        public static byte[] ReadAllBytes(string filename) => File.ReadAllBytes(filename);
    }

    /// <summary>
    /// The file's MAC: HMAC-SHA-256 over everything but the tag itself, truncated to sixteen
    /// bytes.
    /// </summary>
    /// <remarks>
    /// From the platform here, unlike the cipher - .NET has HMAC-SHA-256 and does not have a
    /// bare ChaCha20. Several of the other runtimes are in the same position, which is the
    /// reason the format's tag is HMAC-SHA-256 rather than the Poly1305 that pairs with its
    /// cipher: no platform exposes Poly1305 outside an AEAD, so that choice would have meant
    /// a hand-written implementation in every runtime instead of only where one is needed.
    ///
    /// What it catches is what the structural checks cannot. A block length that does not add
    /// up is a malformed file; four other bytes in an f32 column is a well-formed file holding
    /// a different number, and no check over the file's shape can tell that from data.
    /// </remarks>
    internal static class TcbMac
    {
        /// <summary>Whether the file's MAC field is the tag its own bytes produce.</summary>
        public static bool Verify(byte[] data, byte[] key)
        {
            using var hmac = IncrementalHash.CreateHMAC(HashAlgorithmName.SHA256, key);

            // Two segments: the sixteen bytes the tag lives in cannot be part of what
            // produces it. Skipping them is zeroing them without copying the file.
            hmac.AppendData(data, 0, TcbTable.MacOffset);
            hmac.AppendData(data, TcbTable.KeyCheckOffset, data.Length - TcbTable.KeyCheckOffset);

            // `TryGetHashAndReset` rather than the overload that takes the span and returns the
            // length. That one arrived after netstandard2.1, which is the surface this file has to
            // compile against - it is the reader a Unity project gets, and Unity's API level is
            // netstandard2.1. Both write into the buffer; only this one exists in both places.
            Span<byte> expected = stackalloc byte[32];
            hmac.TryGetHashAndReset(expected, out _);

            return CryptographicOperations.FixedTimeEquals(
                expected[..TcbTable.MacSize],
                new ReadOnlySpan<byte>(data, TcbTable.MacOffset, TcbTable.MacSize));
        }
    }

    /// <summary>
    /// The ChaCha20 stream cipher of RFC 8439, as the file envelope uses it.
    /// </summary>
    /// <remarks>
    /// Here rather than from the platform because the platform's offering is an
    /// authenticated construction, which changes the length. This format wants a plain
    /// keystream: applying it leaves every byte count as it was, so the structural checks -
    /// the block lengths that must sum exactly - hold over the ciphertext unchanged.
    ///
    /// Under two hundred lines with no dependency, which is what lets the same cipher exist
    /// in every runtime that has to read one of these files.
    /// </remarks>
    internal static class ChaCha20
    {
        /// <summary>
        /// Exclusive-ors the keystream over <paramref name="data"/>, in place.
        /// </summary>
        /// <remarks>
        /// One routine for both directions, which is what a stream cipher is: the keystream
        /// depends only on the key, the nonce and the position, so applying it twice returns
        /// what went in. The block counter starts at zero.
        /// </remarks>
        public static void Apply(ReadOnlySpan<byte> key, ReadOnlySpan<byte> nonce, Span<byte> data)
        {
            Span<uint> state = stackalloc uint[16];
            Span<uint> working = stackalloc uint[16];
            Span<byte> keystream = stackalloc byte[64];

            // "expand 32-byte k", as four little-endian words.
            state[0] = 0x61707865;
            state[1] = 0x3320646e;
            state[2] = 0x79622d32;
            state[3] = 0x6b206574;

            for (int at = 0; at < 8; at++)
                state[4 + at] = BinaryPrimitives.ReadUInt32LittleEndian(key.Slice(at * 4, 4));

            state[12] = 0;

            for (int at = 0; at < 3; at++)
                state[13 + at] = BinaryPrimitives.ReadUInt32LittleEndian(nonce.Slice(at * 4, 4));

            for (int offset = 0; offset < data.Length; offset += 64)
            {
                Block(state, working, keystream);

                int count = data.Length - offset < 64 ? data.Length - offset : 64;

                for (int at = 0; at < count; at++)
                    data[offset + at] ^= keystream[at];

                state[12]++;
            }
        }

        /// <summary>One 64-byte keystream block: twenty rounds over a copy of the state.</summary>
        private static void Block(ReadOnlySpan<uint> state, Span<uint> working, Span<byte> keystream)
        {
            state.CopyTo(working);

            // Ten double rounds. Each is four column quarter-rounds and four diagonal ones,
            // which between them let every word reach every other.
            for (int round = 0; round < 10; round++)
            {
                QuarterRound(working, 0, 4, 8, 12);
                QuarterRound(working, 1, 5, 9, 13);
                QuarterRound(working, 2, 6, 10, 14);
                QuarterRound(working, 3, 7, 11, 15);

                QuarterRound(working, 0, 5, 10, 15);
                QuarterRound(working, 1, 6, 11, 12);
                QuarterRound(working, 2, 7, 8, 13);
                QuarterRound(working, 3, 4, 9, 14);
            }

            // Added back to the state it started from, which is what stops the rounds being
            // reversible and so the keystream being recoverable.
            for (int at = 0; at < 16; at++)
            {
                BinaryPrimitives.WriteUInt32LittleEndian(
                    keystream.Slice(at * 4, 4), unchecked(working[at] + state[at]));
            }
        }

        private static void QuarterRound(Span<uint> block, int a, int b, int c, int d)
        {
            unchecked
            {
                block[a] += block[b]; block[d] = RotateLeft(block[d] ^ block[a], 16);
                block[c] += block[d]; block[b] = RotateLeft(block[b] ^ block[c], 12);
                block[a] += block[b]; block[d] = RotateLeft(block[d] ^ block[a], 8);
                block[c] += block[d]; block[b] = RotateLeft(block[b] ^ block[c], 7);
            }
        }

        private static uint RotateLeft(uint value, int count)
            => (value << count) | (value >> (32 - count));
    }

}
